import type { Question, StudyModule } from "../module-types";

const lessons01=[
{title:"Factor of safety and allowable stress",body:"For a ductile material under static loading, the factor of safety compares strength to actual stress: FS=Sy/σ, where Sy is the yield strength and σ is the working (actual) stress. Rearranging gives the allowable stress a designer may use: σallow=Sy/FS. A larger FS means a more conservative design; FS must always come out greater than 1 for a safe part under the stated load."},
{title:"Maximum shear stress (Tresca) theory",body:"For ductile materials, the maximum shear stress theory predicts yielding when the difference between the largest and smallest principal stresses reaches the material's shear strength: σ'=σ1−σ3, using σ1≥σ2≥σ3. Even when a middle principal stress σ2 exists, MSS only uses the extreme two — σ1 and σ3. The theory is conservative (predicts failure sooner) compared to distortion energy."},
{title:"Distortion energy (von Mises) theory",body:"The distortion energy theory computes an effective (von Mises) stress from all stress components. For plane stress with principal stresses σ1 and σ2 (σ3=0): σ'=√(σ1²−σ1σ2+σ2²). With general in-plane stresses σx, σy, τxy: σ'=√(σx²−σxσy+σy²+3τxy²). Yielding is predicted when σ' reaches Sy, so FS=Sy/σ'."},
{title:"Comparing theories and applying safety factors",body:"MSS and DE agree exactly for uniaxial and equal-biaxial stress states but diverge elsewhere — DE is less conservative, predicting up to about 15% higher allowable stress in pure shear (ratio 2/√3). Both apply to ductile materials only; brittle materials use maximum normal stress or Mohr theories instead. When a stress concentration factor Kt applies, multiply the nominal stress by Kt to get the actual peak stress before computing FS."}
];

const flashcards01=[
{front:"Factor of safety",back:"FS=Sy/σ",note:"Strength over stress — always greater than 1 for a safe ductile design."},
{front:"Allowable stress",back:"σallow=Sy/FS",note:"Divide, don't multiply, the yield strength by FS."},
{front:"MSS (Tresca) effective stress",back:"σ'=σ1−σ3",note:"Use the largest and smallest principal stresses, even if a middle σ2 exists."},
{front:"DE (von Mises) — plane stress principal form",back:"σ'=√(σ1²−σ1σ2+σ2²)",note:"σ3=0 for plane stress; don't confuse with the Tresca formula."},
{front:"DE (von Mises) — general plane stress",back:"σ'=√(σx²−σxσy+σy²+3τxy²)",note:"Shear is weighted three times as heavily as normal stress."},
{front:"MSS vs DE in pure shear",back:"τ_DE/τ_MSS=2/√3≈1.15",note:"DE predicts about 15% higher allowable shear strength than MSS."},
{front:"Stress concentration in FS calculations",back:"σmax=Kt·σnom",note:"Apply Kt before dividing into Sy to find the true FS."},
{front:"Theory choice by material",back:"MSS/DE for ductile yielding; max normal stress for brittle fracture",note:"Don't apply a ductile-material theory to a brittle material."}
];

const questions01:Question[]=[
{id:"MD01-Q01",skill:"Factor of safety",difficulty:"Easy",prompt:"A ductile steel part has yield strength Sy=350 MPa and experiences a working stress of 140 MPa. Find the factor of safety.",choices:["0.4","2.0","2.5","3.5"],answer:2,explanation:"FS=Sy/σ=350/140=2.5.",solution:"Step 1 — Factor of safety is FS=Sy/σ.\nStep 2 — Substitute: FS=350/140.\nStep 3 — FS=2.5.\nFinal answer: FS=2.5.",trap:"0.4 comes from inverting the ratio (σ/Sy instead of Sy/σ).",repair:"Factor of safety is always strength over stress, FS=Sy/σ — never the reciprocal."},
{id:"MD01-Q02",skill:"Allowable stress",difficulty:"Easy",prompt:"A component has Sy=300 MPa and must be designed with FS=1.5. Find the allowable stress.",choices:["150 MPa","200 MPa","250 MPa","450 MPa"],answer:1,explanation:"σallow=Sy/FS=300/1.5=200 MPa.",solution:"Step 1 — Allowable stress is σallow=Sy/FS.\nStep 2 — Substitute: σallow=300/1.5.\nStep 3 — σallow=200 MPa.\nFinal answer: 200 MPa.",trap:"450 MPa comes from multiplying Sy by FS instead of dividing.",repair:"Allowable stress equals yield strength divided by the factor of safety, not multiplied — a higher FS should give a lower allowable stress."},
{id:"MD01-Q03",skill:"Maximum shear stress theory",difficulty:"Medium",prompt:"A part has principal stresses σ1=180 MPa, σ2=0, σ3=−60 MPa, and Sy=400 MPa. Find the factor of safety using the maximum shear stress theory.",choices:["1.11","1.67","2.22","3.33"],answer:1,explanation:"σ'=σ1−σ3=240 MPa; FS=400/240≈1.67.",solution:"Step 1 — MSS effective stress: σ'=σ1−σ3=180−(−60)=240 MPa.\nStep 2 — FS=Sy/σ'=400/240.\nStep 3 — FS≈1.67.\nFinal answer: FS≈1.67.",trap:"2.22 comes from using only σ1 (180 MPa) as the effective stress, ignoring σ3.",repair:"Maximum shear stress theory uses the full stress range σ1−σ3, not just the largest principal stress."},
{id:"MD01-Q04",skill:"Von Mises effective stress",difficulty:"Medium",prompt:"A plane-stress element has principal stresses σ1=150 MPa and σ2=−50 MPa. Find the von Mises effective stress.",choices:["158.1 MPa","180.3 MPa","200.0 MPa","230.0 MPa"],answer:1,explanation:"σ'=√(150²−150(−50)+(−50)²)=√32500≈180.3 MPa.",solution:"Step 1 — Plane-stress von Mises: σ'=√(σ1²−σ1σ2+σ2²).\nStep 2 — σ1²=22500, σ1σ2=−7500, σ2²=2500.\nStep 3 — Sum=22500−(−7500)+2500=32500.\nStep 4 — σ'=√32500≈180.3 MPa.\nFinal answer: 180.3 MPa.",trap:"200.0 MPa is the Tresca (maximum shear stress) result σ1−σ2, not the von Mises effective stress.",repair:"Von Mises effective stress requires σ'=√(σ1²−σ1σ2+σ2²) for plane stress — don't substitute the Tresca formula."},
{id:"MD01-Q05",skill:"Factor of safety via von Mises",difficulty:"Medium",prompt:"A plane-stress element has σ1=120 MPa and σ2=−40 MPa, with Sy=250 MPa. Find the factor of safety using the distortion energy theory.",choices:["1.25","1.56","1.73","2.08"],answer:2,explanation:"σ'=√(120²−120(−40)+(−40)²)=√20800≈144.2 MPa; FS=250/144.2≈1.73.",solution:"Step 1 — σ'=√(σ1²−σ1σ2+σ2²)=√(14400+4800+1600)=√20800.\nStep 2 — σ'≈144.2 MPa.\nStep 3 — FS=Sy/σ'=250/144.2.\nStep 4 — FS≈1.73.\nFinal answer: FS≈1.73.",trap:"1.56 comes from using the Tresca value σ1−σ2=160 MPa instead of the von Mises effective stress (144.2 MPa).",repair:"Use the von Mises formula's own effective stress, not the Tresca range, when computing FS with the distortion energy theory."},
{id:"MD01-Q06",skill:"Von Mises with shear",difficulty:"Hard",prompt:"A stressed element has σx=100 MPa, σy=40 MPa, and τxy=30 MPa. Find the von Mises effective stress.",choices:["92.2 MPa","101.5 MPa","110.0 MPa","130.0 MPa"],answer:1,explanation:"σ'=√(100²−100(40)+40²+3(30)²)=√10300≈101.5 MPa.",solution:"Step 1 — General plane-stress von Mises: σ'=√(σx²−σxσy+σy²+3τxy²).\nStep 2 — σx²=10000, σxσy=4000, σy²=1600, 3τxy²=2700.\nStep 3 — Sum=10000−4000+1600+2700=10300.\nStep 4 — σ'=√10300≈101.5 MPa.\nFinal answer: 101.5 MPa.",trap:"92.2 MPa omits the factor of 3 on the shear term (3τxy²), understating the effective stress.",repair:"The plane-stress von Mises formula weights shear three times as heavily as normal stress: σ'=√(σx²−σxσy+σy²+3τxy²)."},
{id:"MD01-Q07",skill:"Maximum shear stress theory (3D)",difficulty:"Hard",prompt:"A component has principal stresses σ1=220 MPa, σ2=100 MPa, σ3=−80 MPa and Sy=500 MPa. Find the factor of safety using the maximum shear stress theory.",choices:["1.67","2.27","3.57","4.17"],answer:0,explanation:"σ'=σ1−σ3=300 MPa; FS=500/300≈1.67.",solution:"Step 1 — MSS uses the largest and smallest principal stresses: σ'=σ1−σ3=220−(−80)=300 MPa.\nStep 2 — FS=Sy/σ'=500/300.\nStep 3 — FS≈1.67.\nFinal answer: FS≈1.67.",trap:"4.17 uses σ1−σ2=120 MPa (ignoring the minimum principal stress σ3), instead of the full range σ1−σ3.",repair:"Maximum shear stress theory always uses the largest and smallest principal stresses (σ1 and σ3), even when a middle stress σ2 exists."},
{id:"MD01-Q08",skill:"Comparing MSS and DE",difficulty:"Hard",prompt:"For a pure shear stress state, the distortion energy theory predicts a higher shear yield strength than the maximum shear stress theory. Find the ratio (DE shear yield strength)/(MSS shear yield strength).",choices:["0.87","1.00","1.15","1.33"],answer:2,explanation:"τ_MSS=Sy/2; τ_DE=Sy/√3; ratio=(Sy/√3)/(Sy/2)=2/√3≈1.15.",solution:"Step 1 — For pure shear, MSS predicts yielding at τ_MSS=Sy/2.\nStep 2 — DE predicts yielding at τ_DE=Sy/√3.\nStep 3 — Ratio=τ_DE/τ_MSS=(Sy/√3)/(Sy/2)=2/√3.\nStep 4 — 2/√3≈1.15.\nFinal answer: ≈1.15.",trap:"0.87 is the inverted ratio (√3/2), i.e. MSS/DE instead of DE/MSS.",repair:"Compute the ratio in the order requested (DE/MSS); inverting the ratio flips whether the result is above or below 1."},
{id:"MD01-Q09",skill:"Stress concentration and FS",difficulty:"Medium",prompt:"A notched part has Sy=420 MPa, nominal stress σnom=95 MPa, and a stress concentration factor Kt=1.8. Find the factor of safety using the actual (peak) stress.",choices:["1.37","2.46","4.42","7.96"],answer:1,explanation:"σmax=Kt·σnom=1.8(95)=171 MPa; FS=420/171≈2.46.",solution:"Step 1 — Actual peak stress: σmax=Kt·σnom=1.8(95)=171 MPa.\nStep 2 — FS=Sy/σmax=420/171.\nStep 3 — FS≈2.46.\nFinal answer: FS≈2.46.",trap:"4.42 uses the nominal stress directly (420/95) and forgets to multiply by the stress concentration factor Kt before computing FS.",repair:"Always apply the stress concentration factor to get the actual peak stress (σmax=Kt·σnom) before dividing into Sy."},
{id:"MD01-Q10",skill:"Factor of safety",difficulty:"Easy",prompt:"A shaft has Sy=560 MPa and carries a working stress of 280 MPa. Find the factor of safety.",choices:["1.0","2.0","2.8","4.0"],answer:1,explanation:"FS=560/280=2.0.",solution:"Step 1 — FS=Sy/σ.\nStep 2 — FS=560/280.\nStep 3 — FS=2.0.\nFinal answer: FS=2.0.",trap:"4.0 comes from mistakenly halving the working stress (280/2=140) before dividing into Sy.",repair:"Use the actual working stress exactly as given — don't apply extra factors that aren't stated in the problem."}
];

const lessons02=[
{title:"Bolt preload and torque-tension",body:"Tightening torque relates to bolt preload through T=KFd, where F is the desired clamping (preload) force, d is the nominal bolt diameter, and K is the nut factor accounting for thread and under-head friction. For standard non-plated steel fasteners, K≈0.2 is a common design estimate; lubricated or plated threads can lower K substantially."},
{title:"Keys and keyways",body:"A key transmits torque between a shaft and hub by shear across its cross-section. The tangential force on the key follows from the shaft torque and radius: F=T/(d/2)=2T/d. The key must be sized so the shear stress τ=F/(w·L) and bearing stress σb=2F/(h·L) both stay below allowable limits, where w is key width, h is key height, and L is key length."},
{title:"Shaft bearing reactions",body:"Radial loads from gears, pulleys, or sprockets mounted on a shaft are carried by the supporting bearings. Treat the shaft as a simply supported beam and use static equilibrium — sum of forces and sum of moments about one support — to find each bearing's reaction load before selecting a bearing rated for that load."},
{title:"Preload level and fastener capacity",body:"A bolt's proof load is Fp=At·Sp, using the tensile stress area At and the material's proof strength Sp. Design guidelines recommend preloading to about 75% of proof load for connections that may be reused, and about 90% for permanent connections, to maximize joint clamping without risking overload during assembly."}
];

const flashcards02=[
{front:"Torque-tension relation",back:"T=KFd",note:"K is the nut factor; ≈0.2 for standard dry steel fasteners."},
{front:"Nut factor K (typical)",back:"K≈0.2 (dry steel)",note:"Lower with lubrication or plating."},
{front:"Key tangential force",back:"F=2T/d",note:"Uses the shaft radius (d/2), not the full diameter."},
{front:"Key shear stress",back:"τ=F/(wL)",note:"w=key width, L=key length."},
{front:"Key bearing stress",back:"σb=2F/(hL)",note:"Only half the key height h resists crushing on one side."},
{front:"Bolt proof load",back:"Fp=At·Sp",note:"At is tensile stress area, Sp is proof strength."},
{front:"Recommended preload",back:"Fi=0.75Fp (reused), 0.90Fp (permanent)",note:"Match the factor to the connection type."},
{front:"Bolt shank area",back:"A=πd²/4",note:"Circular cross-section — don't substitute d² directly."}
];

const questions02:Question[]=[
{id:"MD02-Q01",skill:"Torque-tension relation",difficulty:"Easy",prompt:"A bolted joint needs a preload of F=20 kN using a bolt with d=12 mm and a nut factor K=0.2. Find the required tightening torque.",choices:["24 N·m","48 N·m","96 N·m","240 N·m"],answer:1,explanation:"T=KFd=0.2(20000)(0.012)=48 N·m.",solution:"Step 1 — T=KFd.\nStep 2 — Substitute: T=0.2(20000)(0.012).\nStep 3 — T=48 N·m.\nFinal answer: 48 N·m.",trap:"240 N·m results from omitting the nut factor K (effectively using K=1.0) instead of the typical dry-steel value K≈0.2.",repair:"Always include the nut factor K in T=KFd — it accounts for thread friction and typically runs around 0.2 for standard steel fasteners."},
{id:"MD02-Q02",skill:"Torque-tension relation",difficulty:"Easy",prompt:"A torque wrench is set to 60 N·m on a bolt with d=10 mm and K=0.2. Find the resulting preload.",choices:["3 kN","6 kN","30 kN","60 kN"],answer:2,explanation:"F=T/(Kd)=60/(0.2×0.01)=30000 N=30 kN.",solution:"Step 1 — Rearrange T=KFd for preload: F=T/(Kd).\nStep 2 — Substitute: F=60/(0.2×0.01)=60/0.002.\nStep 3 — F=30000 N=30 kN.\nFinal answer: 30 kN.",trap:"6 kN comes from omitting the nut factor K (F=T/d) instead of F=T/(Kd).",repair:"Rearrange T=KFd carefully — solving for preload requires dividing by both K and d: F=T/(Kd)."},
{id:"MD02-Q03",skill:"Key shear stress",difficulty:"Medium",prompt:"A square key with width w=8 mm and length L=40 mm transmits T=150 N·m on a shaft of diameter d=32 mm. Find the shear stress in the key.",choices:["14.6 MPa","22.0 MPa","29.3 MPa","58.6 MPa"],answer:2,explanation:"F=2T/d=9375 N; τ=F/(wL)=9375/(0.008×0.04)≈29.3 MPa.",solution:"Step 1 — Tangential force on the key: F=2T/d=2(150)/0.032=9375 N.\nStep 2 — Shear area: A=wL=0.008×0.04=0.00032 m².\nStep 3 — τ=F/A=9375/0.00032.\nStep 4 — τ≈29,296,875 Pa≈29.3 MPa.\nFinal answer: 29.3 MPa.",trap:"14.6 MPa comes from using F=T/d instead of F=2T/d — the tangential key force equals torque divided by the shaft radius (d/2), not the diameter.",repair:"Convert torque to key force using the shaft radius: F=T/(d/2)=2T/d, then divide by the key's shear area (w×L)."},
{id:"MD02-Q04",skill:"Bolt preload from proof strength",difficulty:"Medium",prompt:"An M12 class 8.8 bolt has tensile stress area At=84.3 mm² and proof strength Sp=660 MPa. For a reused (non-permanent) connection, recommended preload is Fi=0.75Fp. Find Fi.",choices:["31.3 kN","41.7 kN","50.0 kN","55.6 kN"],answer:1,explanation:"Fp=At Sp=84.3(660)=55,638 N; Fi=0.75(55.638)≈41.7 kN.",solution:"Step 1 — Proof load: Fp=At·Sp=84.3(660)=55,638 N=55.64 kN.\nStep 2 — Recommended preload for a reused joint: Fi=0.75Fp.\nStep 3 — Fi=0.75(55.64)≈41.7 kN.\nFinal answer: ≈41.7 kN.",trap:"50.0 kN uses the 0.90 preload factor recommended for permanent (non-reused) connections instead of the 0.75 factor specified for a reused connection.",repair:"Match the preload factor to the connection type stated in the problem: 0.75·Fp for reused joints, 0.90·Fp for permanent ones."},
{id:"MD02-Q05",skill:"Key bearing stress",difficulty:"Medium",prompt:"For the same key as before (w=8 mm, L=40 mm, h=8 mm, F=9375 N), find the bearing (crushing) stress on the key.",choices:["29.3 MPa","44.0 MPa","58.6 MPa","87.9 MPa"],answer:2,explanation:"σb=2F/(hL)=2(9375)/(0.008×0.04)≈58.6 MPa.",solution:"Step 1 — Bearing stress uses only half the key height: σb=2F/(hL).\nStep 2 — Substitute: σb=2(9375)/(0.008×0.04)=18750/0.00032.\nStep 3 — σb≈58,593,750 Pa≈58.6 MPa.\nFinal answer: 58.6 MPa.",trap:"29.3 MPa is the key's shear stress (using the full height), not bearing stress — bearing stress uses only half the key height in contact, doubling the effective pressure: σb=2F/(hL).",repair:"Bearing (crushing) stress on a key loads only half its height, so σb=2F/(hL), not F/(hL)."},
{id:"MD02-Q06",skill:"Bolt group shear capacity",difficulty:"Hard",prompt:"A bolted bracket carries a total shear load of 60 kN. Each bolt has diameter d=10 mm and allowable shear stress τallow=150 MPa. Find the minimum number of bolts required.",choices:["4","5","6","8"],answer:2,explanation:"A=πd²/4=7.854e-5 m²; F_bolt=150e6(7.854e-5)≈11,781 N; n=60000/11781≈5.09→6 bolts.",solution:"Step 1 — Bolt shear area: A=πd²/4=π(0.01)²/4≈7.854×10⁻⁵ m².\nStep 2 — Capacity per bolt: F=τallow·A=150×10⁶(7.854×10⁻⁵)≈11,781 N.\nStep 3 — n=60000/11781≈5.09.\nStep 4 — Round up: n=6 bolts.\nFinal answer: 6 bolts.",trap:"4 bolts results from using A=d² instead of A=πd²/4 for the bolt's circular cross-section, overstating each bolt's capacity.",repair:"Bolt shank area is circular: A=πd²/4 — don't substitute the diameter squared directly, and always round the bolt count up."},
{id:"MD02-Q07",skill:"Key length from torque",difficulty:"Hard",prompt:"A shaft of diameter d=40 mm transmits T=300 N·m through a key of width w=10 mm. Allowable key shear stress is 70 MPa. Find the minimum key length.",choices:["10.7 mm","21.4 mm","30.0 mm","42.9 mm"],answer:1,explanation:"F=2T/d=15000 N; L=F/(wτallow)=15000/(0.01×70e6)≈21.4 mm.",solution:"Step 1 — Tangential force: F=2T/d=2(300)/0.04=15,000 N.\nStep 2 — Rearrange τ=F/(wL) for length: L=F/(w·τallow).\nStep 3 — L=15000/(0.01×70×10⁶)=15000/700000.\nStep 4 — L≈0.02143 m≈21.4 mm.\nFinal answer: ≈21.4 mm.",trap:"10.7 mm comes from using F=T/d instead of F=2T/d for the tangential force on the key, understating the required length.",repair:"The force transmitted through a key equals torque divided by the shaft radius (d/2), i.e. F=2T/d — using the full diameter understates the force and required key length."},
{id:"MD02-Q08",skill:"Torque range from K-factor variation",difficulty:"Hard",prompt:"For a target preload of F=25 kN on a d=14 mm bolt, the nut factor K can range from 0.15 to 0.20. Find the spread between the maximum and minimum tightening torque.",choices:["17.5 N·m","52.5 N·m","70.0 N·m","122.5 N·m"],answer:0,explanation:"T_min=0.15(25000)(0.014)=52.5 N·m; T_max=0.20(25000)(0.014)=70.0 N·m; spread=17.5 N·m.",solution:"Step 1 — T_min=K_min·F·d=0.15(25000)(0.014)=52.5 N·m.\nStep 2 — T_max=K_max·F·d=0.20(25000)(0.014)=70.0 N·m.\nStep 3 — Spread=T_max−T_min=70.0−52.5.\nStep 4 — Spread=17.5 N·m.\nFinal answer: 17.5 N·m.",trap:"70.0 N·m is the maximum torque itself, not the spread between minimum and maximum torque caused by K-factor variation.",repair:"When asked for a torque range or spread, subtract T_min from T_max — don't report either endpoint alone."},
{id:"MD02-Q09",skill:"Shaft bearing reactions",difficulty:"Medium",prompt:"A shaft is supported by bearings A and B, 600 mm apart. A gear applies a radial load of 2000 N at a point 150 mm from bearing A (450 mm from bearing B). Find the reaction at bearing A.",choices:["500 N","1000 N","1500 N","2000 N"],answer:2,explanation:"Sum moments about B: R_A(600)=2000(450); R_A=1500 N.",solution:"Step 1 — Sum moments about bearing B: R_A(600)=2000(600−150).\nStep 2 — R_A(600)=2000(450)=900,000.\nStep 3 — R_A=900000/600=1500 N.\nFinal answer: 1500 N (and R_B=500 N).",trap:"500 N is the reaction at bearing B, not bearing A — check which support the moment equation was summed about.",repair:"Sum moments about the far bearing to solve for the near one; the load closer to a support carries more of the reaction."},
{id:"MD02-Q10",skill:"Torque-tension relation",difficulty:"Easy",prompt:"A bolt needs a preload of 15 kN. Using T=KFd with K=0.2 and d=8 mm, find the required torque.",choices:["12 N·m","24 N·m","48 N·m","120 N·m"],answer:1,explanation:"T=0.2(15000)(0.008)=24 N·m.",solution:"Step 1 — T=KFd.\nStep 2 — Substitute: T=0.2(15000)(0.008).\nStep 3 — T=24 N·m.\nFinal answer: 24 N·m.",trap:"12 N·m results from using the bolt radius (4 mm) instead of the nominal diameter (8 mm) in T=KFd.",repair:"T=KFd always uses the nominal bolt diameter, not the radius."}
];

const lessons03=[
{title:"Belt and pulley speed ratio",body:"For a belt connecting two pulleys with no slip, the belt's linear speed is the same at both pulleys, giving N1d1=N2d2. A larger driven pulley always rotates slower than a smaller driver, and vice versa — speed and diameter are inversely related."},
{title:"Gear ratio and torque",body:"For meshing gears, tooth counts play the same role as pulley diameters: N2=N1×(teeth1/teeth2). Assuming an ideal (lossless) mesh, power is conserved, so torque and speed are inversely related: torque2/torque1=N1/N2=teeth2/teeth1 — the gear that spins slower carries proportionally more torque."},
{title:"Shaft power",body:"Power transmitted by a rotating shaft is P=Tω, where ω is the angular velocity in rad/s. Convert rotational speed from rpm using ω=2πN/60. Equivalently, P=2πNT/60 lets you compute power directly from torque and rpm without a separate conversion step."},
{title:"Efficiency and belt power",body:"Real transmissions lose some power to friction; overall efficiency of stages in series is the product of each stage's efficiency, η_total=η1×η2×.... For a flat belt drive, transmitted power depends on the difference between tight-side and slack-side tension: P=(T1−T2)v, where v is the belt's linear speed — not either tension alone."}
];

